import _socket
import socket
import select
import signal


print(socket.AF_INET)
print(socket.SOCK_STREAM)
s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
print(s.family)
print(s.type)
print(s.fileno() >= 0)
s.settimeout(1)
print(s.gettimeout())
print(select.select([], [], [], 0))
s.close()
option_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
option_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, b"\x01\x00\x00\x00")
print(option_socket.getsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR))
try:
    option_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, object())
except Exception as exc:
    print(type(exc).__name__)
option_socket.close()
print(_socket.AF_INET)
print(isinstance(_socket.gethostname(), str), bool(_socket.gethostname()))
print(_socket.getprotobyname("tcp"))
print(_socket.getservbyname("http", "tcp"), _socket.getservbyport(80, "tcp"))
try:
    _socket.htonl(-1)
except Exception as exc:
    print(type(exc).__name__)
host_info = _socket.gethostbyname_ex("localhost")
print(isinstance(host_info, tuple), host_info[1] == [], "127.0.0.1" in host_info[2])
reverse_info = _socket.gethostbyaddr("127.0.0.1")
print(isinstance(reverse_info, tuple), len(reverse_info) == 3, "127.0.0.1" in reverse_info[2])
print(_socket.inet_ntop(_socket.AF_INET6, _socket.inet_pton(_socket.AF_INET6, "::1")))
print(_socket.inet_ntoa(_socket.inet_aton("127.0.0.1")))
ipv6_rows = _socket.getaddrinfo("::1", 0, _socket.AF_INET6)
print(bool(ipv6_rows), ipv6_rows[0][0] == _socket.AF_INET6, len(ipv6_rows[0][4]))
ipv6_socket = socket.socket(_socket.AF_INET6, _socket.SOCK_DGRAM)
print(ipv6_socket.family == _socket.AF_INET6, ipv6_socket.fileno() >= 0)
ipv6_socket.close()

ipv6_receiver = socket.socket(_socket.AF_INET6, _socket.SOCK_DGRAM)
ipv6_receiver.bind(("::1", 0, 0, 0))
ipv6_sender = socket.socket(_socket.AF_INET6, _socket.SOCK_DGRAM)
ipv6_sender.sendto(b"v6", ipv6_receiver.getsockname())
ipv6_packet, ipv6_address = ipv6_receiver.recvfrom(8)
print(ipv6_packet, len(ipv6_address), ipv6_address[0] == "::1")
ipv6_sender.close()
ipv6_receiver.close()

ipv6_server = socket.socket(_socket.AF_INET6, _socket.SOCK_STREAM)
ipv6_server.bind(("::1", 0, 0, 0))
ipv6_server.listen()
ipv6_client = socket.socket(_socket.AF_INET6, _socket.SOCK_STREAM)
ipv6_client.connect(ipv6_server.getsockname())
ipv6_accepted, ipv6_peer = ipv6_server.accept()
ipv6_client.sendall(b"6")
print(len(ipv6_client.getsockname()), len(ipv6_client.getpeername()), len(ipv6_peer), ipv6_accepted.recv(1))
ipv6_accepted.close()
ipv6_client.close()
ipv6_server.close()

print(_socket.getnameinfo(("::1", 0, 0, 0), _socket.NI_NUMERICHOST | _socket.NI_NUMERICSERV))

receiver = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
receiver.bind(("127.0.0.1", 0))
sender = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
print(sender.sendto(b"udp", receiver.getsockname()))
packet, address = receiver.recvfrom(16)
print(packet, address[0] == "127.0.0.1")
sender.sendto(b"xy", receiver.getsockname())
target = bytearray(4)
count, address = receiver.recvfrom_into(target)
print(count, bytes(target[:count]), address[0] == "127.0.0.1")
sender.close()
receiver.close()

peek_left, peek_right = socket.socketpair()
peek_left.sendall(b"p")
print(peek_right.recv(1, _socket.MSG_PEEK), peek_right.recv(1))
peek_left.close()
peek_right.close()

into_left, into_right = socket.socketpair()
into_left.sendall(b"q")
into_buffer = bytearray(1)
print(into_right.recv_into(into_buffer, 1, _socket.MSG_PEEK), bytes(into_buffer), into_right.recv(1))
into_left.close()
into_right.close()

left, right = socket.socketpair()
left.sendall(b"close-write", 0)
left.shutdown(socket.SHUT_WR)
print(right.recv(32), right.recv(1))
left.close()
right.close()

print(signal.SIGBREAK, 21 in signal.valid_signals())
handler = lambda signum, frame: None
old = signal.signal(signal.SIGBREAK, handler)
print(signal.signal(signal.SIGBREAK, old) is handler)
for signum in (-1, 7):
    try:
        signal.signal(signum, handler)
    except ValueError:
        print(True)
raised_signals = []
signal.signal(signal.SIGBREAK, lambda signum, frame: raised_signals.append(signum))
signal.raise_signal(signal.SIGBREAK)
print(raised_signals)
signal.signal(signal.SIGBREAK, signal.SIG_DFL)
try:
    signal.raise_signal(-1)
except ValueError:
    print(True)
inheritable_socket = _socket.socket()
print(inheritable_socket.get_inheritable())
inheritable_socket.set_inheritable(True)
print(inheritable_socket.get_inheritable())
inheritable_socket.set_inheritable(False)
print(inheritable_socket.get_inheritable())
inheritable_socket.close()
blocking_socket = _socket.socket()
print(blocking_socket.getblocking())
blocking_socket.setblocking(False)
print(blocking_socket.getblocking())
blocking_socket.setblocking(True)
print(blocking_socket.getblocking())
blocking_socket.close()
inherit_listener = _socket.socket()
inherit_listener.bind(("127.0.0.1", 0))
inherit_listener.listen(1)
inherit_client = _socket.socket()
inherit_client.connect(inherit_listener.getsockname())
inherit_accepted, _ = inherit_listener.accept()
print(inherit_accepted.get_inheritable())
inherit_client.close()
inherit_accepted.close()
inherit_listener.close()

dup_left, dup_right = socket.socketpair()
dup_copy = dup_left.dup()
print(dup_copy.fileno() != dup_left.fileno(), dup_copy.gettimeout() == dup_left.gettimeout())
print(dup_copy.get_inheritable())
dup_copy.set_inheritable(True)
print(dup_copy.get_inheritable())
dup_copy.set_inheritable(False)
print(dup_copy.get_inheritable())
dup_left.close()
dup_copy.sendall(b"dup")
print(dup_right.recv(3))
dup_copy.close()
dup_right.close()
